def _xavfsiz():
    src = (ROOT / "samtm_platform.py").read_text(encoding="utf-8")
    i = src.index("def _ai_media_svg_xavfsizmi")
    j = src.index("\ndef ", i + 10)
    ns = {"re": re}
    exec(src[i:j], ns)
    return ns["_ai_media_svg_xavfsizmi"]


def test_rasmlar_bor_xavfsiz_yengil():
    ok = _xavfsiz()
    assert len(NOMLAR) == 429   # manifestdagi hamma rasm
    for n in NOMLAR:
        data = (SVG / f"{n}.svg").read_bytes()
        assert data.lstrip().startswith(b"<svg"), n
        assert ok(data), n
        assert len(data) < 160_000, n
        assert (PRE / f"{n}.png").is_file(), n


def test_harakat_qisqa_va_tinchlanadi():
    for n in NOMLAR:
        t = (SVG / f"{n}.svg").read_text(encoding="utf-8")
        assert "@keyframes" in t and "prefers-reduced-motion" in t, n
        assert "infinite" not in t, n
    # ma'noga mos effektlar
    assert ">z<" in (SVG / "en34-u1-good-night.svg").read_text(encoding="utf-8")
    assert ">?<" in (SVG / "en45-u3-how-many.svg").read_text(encoding="utf-8")
    assert ">11<" in (SVG / "en67-u1-eleven.svg").read_text(encoding="utf-8")
